/* The goal of this visualisation is to visually explain
Chebyshev polynomials as cosines on a cylinder. The white band is
the origin (x = 0) in cylinder coordinates but x = +1 for the
Chebyshev polynomial.

Ergo if a Chebyshev polynomial is a cosine on a cylinder, that
means that decomposing a function in the [-1 , +1] range into a
series of Chebyshev polynomials is exactly the same as projecting
that function onto a cylinder and then performing cosine Fourier
analysis on the unrolled cylinder, so the multiplier for each
Chebyshev polynomial will be the same as the multiplier of the
matching cosine. Understanding this quickly explains all the
characteristics of decomposing a function into a series of
Chebyshev polynomials as the way to sample the function derives
intuitively from understanding this cylindrical relationship, and
all other familiar concepts from Fourier analysis such as
aliasing apply. In case you're curious to make practical use of
Chebyshev analysis, the best way to make use of Chebyshev
polynomials is to use Clenshaw summation, which only takes 1 mul,
1 add and 1 sub per degree.

I reused my polygon drawing function from my "Fast Gaussian-blurred
polygon" shader, so the antialiasing comes from directly
approximating the Gaussian-weighted area of each polygon. I added
a function to decide whether or not to draw a polygon, but even
though it's simple, it slows everything down an awful lots for
what it does. I guess the inconsistent branching doesn't help,
but I don't really get why it's so bad.

The flattening effect to show how the cylinder without
perspective is exactly a Chebyshev polynomial is achieved by
moving the camera much further away and making it zoom in to make
up for it. The distance/zoom level is controlled using error
functions (the integral of the Gaussian function), and the
spinning rate is controlled by the error function's integral,
which is a very useful but rarely used way to transition from one
slope to another in a smooth Gaussian way. Get on my Gaussian level.
*/

#define pi 3.1415927

float sq(float x)
{
    return x * x;
}

float gaussian(float x)
{
	return exp(-x*x);
}

float erf_fast(float x)
{
	float y, xa = abs(x);

	// erf(x) ~= 1 - exp(<polynomial>) for x >= 0, max error 1/4249
	// 2 mad, 1 mul, 1 +-, 1 copysign, 1 exp = ~9 FR
	y = ((-0.06388*xa - 0.66186)*xa - 1.123613)*xa;
	y = 1. - exp(y);
	y *= sign(x);

	return y;
}

float integral_of_erfr(float x)
{
	return (x*erf_fast(x) + gaussian(x)*(1./sqrt(pi)) + x) * 0.5;
}

float erf_right_triangle_acute_integral(float x, float y)
{
	float x2 = x*x, y2 = y*y;
	float v = (((((-1.6663128e-05*y2 + 5.104393e-06)*x2 +
			0.0005496131*y2 - 5.30433e-05)*x2 +
			(0.0001584783*y2 - 0.00741157237)*y2 - 0.0018265954)*x2 +
			(-0.003881739*y2 + 0.0523013844)*y2 + 0.04582956)*x2 +
			((-0.00368418*y2 + 0.03692744)*y2 - 0.1996548)*y2 - 0.50360028)*x2 +
			((-0.0012717*y2 - 0.0101518)*y2 + 0.0109084)*y2 - 1.836892;
	return exp(v) * x2 * y;	// 25 FR
}

float calc_right_triangle_pixel_weight(vec2 rp)
{
	vec2 rpa;
	bool use_obtuse;
	float slope, acute, obtuse;

	rpa = abs(rp);

	// Pick method
	use_obtuse = rpa.y > rpa.x;
	if (use_obtuse)			// if we use the obtuse method
	{
		// Swap axes
		float t = rp.x;
		rp.x = rp.y;
		rp.y = t;
	}

	// Prepare the arguments (slope and clamped x)
	slope = abs(rp.x) < 1e-5 ? 0. : rp.y / rp.x;
	slope = clamp(slope, -1., 1.);
	rp.x = clamp(rp.x, -3., 3.);

	acute = erf_right_triangle_acute_integral(rp.x, slope);
	obtuse = 0.25 * erf_fast(rp.y) * erf_fast(rp.x) - acute;
	acute = abs(acute) * sign(slope);
	obtuse = abs(obtuse) * sign(slope);

	return use_obtuse ? obtuse : acute;
}

float calc_subtriangle_pixel_weight(vec2 p0, vec2 p1)
{
	vec2 rot, r0, r1, np;
	float weight;

	// Rotate points
	rot = normalize(p1 - p0);
	r0.x = rot.x*p0.y - rot.y*p0.x;
	r0.y = rot.x*p0.x + rot.y*p0.y;
	r1.x = r0.x;
	r1.y = rot.x*p1.x + rot.y*p1.y;

	// Calc weights
	weight = calc_right_triangle_pixel_weight(r1);
	weight -= calc_right_triangle_pixel_weight(r0);

	return weight;
}

vec3 draw_tetragon(vec2 p[4], vec3 col, float rad, vec3 pv, vec2 pf)
{
	float weight;

	// Transform polygon coordinates
	p[0] = (p[0] - pf) * rad;
	p[1] = (p[1] - pf) * rad;
	p[2] = (p[2] - pf) * rad;
	p[3] = (p[3] - pf) * rad;

	// Calculate weight for each subtriangle
	weight = calc_subtriangle_pixel_weight(p[0], p[1]);
	weight += calc_subtriangle_pixel_weight(p[1], p[2]);
	weight += calc_subtriangle_pixel_weight(p[2], p[3]);
	weight += calc_subtriangle_pixel_weight(p[3], p[0]);

	// Apply weight to colour
	pv += weight * col;

	return pv;
}

