bool must_draw_tetragon(vec2 p[4], float rad, vec2 pf)
{
    //return sdTetragon(pf, p) < 3.*rad;    // too slow

    float grad = 3. * rad;
    vec2 pmin = p[0], pmax = p[0];

    for (int i=0; i < 4; i++)
    {
        pmin = min(pmin, p[i] - grad);
        pmax = max(pmax, p[i] + grad);
    }

    return pf.x > pmin.x && pf.x < pmax.x;
    // This is surprisingly overall slower:
    //return pf.x > pmin.x && pf.y > pmin.y && pf.x < pmax.x && pf.y < pmax.y;
}

vec3 lsrgb(vec3 l)	// converts a [0.0, 1.0] linear value into a [0.0, 1.0] sRGB value
{
	vec3 line = l * 12.92;
	vec3 x = sqrt(l);
	vec3 curve = ((((0.455*x - 1.48)*x + 1.92137)*x - 1.373254)*x + 1.51733216)*x - 0.0404733783;
	return mix(line, curve, greaterThan(l, vec3(0.0031308)));
}

vec3 gamut_limiter(vec3 pv)
{
    // Find the maximum of the 3 channels
    float vmax = max(pv.x, max(pv.y, pv.z));

    if (vmax > 1.)   // if the colour is out of gamut
    {
        // Luminosity of the colour's grey point
        float L = 0.16*pv.x + 0.73*pv.y + 0.11*pv.z;

		if (L < 1.) // if the grey point is no brighter than white
		{
			// t represents the ratio on the line between the input colour
			// and its corresponding grey point. t is between 0 and 1,
			// a lower t meaning closer to the grey point and a
			// higher t meaning closer to the input colour
			float t = (1.-L) / (vmax-L);

			// a simple linear interpolation between the
			// input colour and its grey point
            pv = mix(vec3(L), pv, t);
		}
		else    // if it's too bright regardless of saturation
		{
			pv = vec3(1.);
		}
    }

    return pv;
}

vec3 get_vertex(const int poly_id, const int vertex_id, const float order)
{
    //return texture(iChannel0, vec2(float(poly_id)+0.5, float(vertex_id)+0.5)/iResolution.xy).xyz;        
    vec2 vertex_offset = vec2(float(vertex_id & 1), float(vertex_id >> 1));

    vec3 p;

    const float rad = 1.8;
    float th = 2.*pi * (float(poly_id) + vertex_offset.x) * (1./float(POLY_COUNT));

    p.x = rad * cos(th);
    p.z = rad * sin(th);
    p.y = (1.5 + cos(th * order)) * vertex_offset.y - 1.25;

    return p;
}

int gray(int num)
{
    return num ^ (num >> 1);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 p[4];
    vec3 pv = vec3(0.);
    vec3 cam_pos = vec3(0., 0., -9.);
    float zoom = 2.45;

    // Subdivide screen
    vec2 grid = vec2(3., 2.);
    vec2 m = fragCoord * grid/vec2(iResolution);
    vec2 mapped_coord = (m-floor(m))*vec2(iResolution)/grid + 0.5*vec2(iResolution) - 0.5*vec2(iResolution)/grid;
    float order = (grid.y-1. - floor(m).y) * grid.x + floor(m).x;

    // Pixel to world coordinates
    float scrscale = 2. / iResolution.y;
    vec2 uv = (mapped_coord-iResolution.xy*0.5) * scrscale;

    // Animation parameters
    float t_anim = iTime / 16.;           // animation periodicity
    t_anim = t_anim - floor(t_anim);
    const float anim_trans = 30.;         // higher makes the speed transition quicker
    const float anim_pad = 4.4;            // in Gaussian units
    float angle_anim = (integral_of_erfr(t_anim*anim_trans-anim_pad)-integral_of_erfr(t_anim*anim_trans-(anim_trans-anim_pad)))
                        / (anim_trans-2.*anim_pad);
    const float max_zoom_mul = 1. / 100.;
    float zoom_anim = 1. / (max_zoom_mul + (1.-max_zoom_mul)*0.5*(erf_fast(t_anim*anim_trans-anim_pad)-erf_fast(t_anim*anim_trans-(anim_trans-anim_pad))));
    zoom *= zoom_anim;
    cam_pos *= zoom_anim;

    for (int ip = 0; ip < POLY_COUNT; ip++)
    {
        // Tetragon rotation
        float th = angle_anim * 2.*pi;
        float costh = cos(th);
        float sinth = sin(-th);

        float depth = 0.;
        for (int iv=0; iv < 4; iv++)
        {
            vec3 v = get_vertex(ip, gray(iv), order);

            // Rotation
            v.xz = vec2(v.x * costh - v.z * sinth, v.x * sinth + v.z * costh);

            depth += v.z;
            v -= cam_pos;
            p[iv] = zoom * v.xy / v.z;
        }

        depth *= 0.25;

        // Varying blurriness
        float rad = sq(1.-abs(cos(0.*iTime * 6.2831853 / 16.))) * 0.04;
        float min_rad = 0.8*scrscale;
        rad = length(vec2(rad, min_rad));

        // Draw the polygon
        if (must_draw_tetragon(p, rad, uv))
        {
            vec3 col = vec3(0., 0.1, 0.4);
            col *= exp(-(depth+8.)*0.75)*300.;
            if (ip == 0 || ip == POLY_COUNT-1)
                col *= 2.5;
            else if ((ip & 7) == 0)
                col *= 0.56;
            col *= 1. + 1./20.*(mod(float(ip) * 0.5, 1.)-0.5);
            pv += abs(-(draw_tetragon(p, col, 1./rad, vec3(0.), uv)));
        }
    }

    // Output to screen
    fragColor = vec4(lsrgb(gamut_limiter(pv)), 1.);
}
